// Manually inject EchoLidar into the autogenerated ExpoModulesProvider.swift.
// Workaround for expo-modules-autolinking@55.0.18 not including local Expo
// modules in its resolve output. Run this after every `pod install` if the
// Podfile at_exit hook doesn't fire (e.g. if pod-install runs in a child
// process whose at_exit doesn't propagate).

const fs = require('fs');
const path = require('path');

const projectRoot = path.resolve(__dirname, '..');
const providerPath = path.join(
  projectRoot,
  'ios',
  'Pods',
  'Target Support Files',
  'Pods-echolocation',
  'ExpoModulesProvider.swift'
);

if (!fs.existsSync(providerPath)) {
  console.error('[patch-expo-modules-provider] file not found:', providerPath);
  process.exit(1);
}

let content = fs.readFileSync(providerPath, 'utf8');
if (content.includes('EchoLidar')) {
  console.log('[patch-expo-modules-provider] EchoLidar already registered');
  process.exit(0);
}

const before = content;
content = content.replace(
  /(\n)(@objc\(ExpoModulesProvider\))/,
  '\ninternal import EchoLidar\n$2'
);
content = content.replace(
  /(\(module: WebBrowserModule\.self, name: nil\))(\n\s*\])/,
  '$1,\n      (module: EchoLidarModule.self, name: nil)$2'
);

if (content === before) {
  console.error('[patch-expo-modules-provider] regex did not match — file shape changed');
  process.exit(2);
}

fs.writeFileSync(providerPath, content);
console.log('[patch-expo-modules-provider] PATCHED: EchoLidar added');
